mapper.select:
SELECT s.station_id AS stationId, s.station_name AS name, s.address, s.latitude AS lat, s.longitude AS lng, s.total_piles AS totalPiles, s.available_piles AS freePiles, s.occupying_piles, s.parking_fee AS parkFee, s.open_time, s.close_time, s.images, ROUND(6371 * 2 * ASIN(SQRT( POW(SIN((#{lat} - s.latitude) * PI() / 360), 2) + COS(#{lat} * PI() / 180) * COS(s.latitude * PI() / 180) * POW(SIN((#{lng} - s.longitude) * PI() / 360), 2) )), 1) AS distance, s.facilities_info AS facilitiesInfo, s.station_status AS stationStatus FROM stad_charging_station s WHERE s.station_status = '1' AND s.total_piles > 0 ORDER BY
distance s.station_id s.create_time
ASC DESC LIMIT #{offset}, #{limit}

SELECT 
FROM stad_charging_station s
WHERE s.station_id = #{stationId}
